-- Seed the current shared application configuration without copying users or hibah records.

ON DUPLICATE KEY UPDATE field_label = VALUES(field_label), field_key = VALUES(field_key), field_type = VALUES(field_type), field_options = VALUES(field_options), field_placeholder = VALUES(field_placeholder), field_description = VALUES(field_description), is_required = VALUES(is_required), display_order = VALUES(display_order), is_active = VALUES(is_active);

ON DUPLICATE KEY UPDATE field_label = VALUES(field_label), field_key = VALUES(field_key), field_type = VALUES(field_type), field_options = VALUES(field_options), field_placeholder = VALUES(field_placeholder), field_description = VALUES(field_description), is_required = VALUES(is_required), display_order = VALUES(display_order), is_active = VALUES(is_active);

ON DUPLICATE KEY UPDATE setting_value = VALUES(setting_value), updated_at = CURRENT_TIMESTAMP;

UPDATE app_metadata SET meta_value = '1' WHERE meta_key IN ('data_initialized', 'verification_fields_initialized');
