INSERT INTO app_settings (setting_key, setting_value) VALUES
('announcement', CONCAT('Hibah dari pemerintah daerah adalah pemberian uang, barang, atau jasa yang bersumber dari Anggaran Pendapatan dan Belanja Daerah (APBD) kepada pihak lain yang bertujuan untuk menunjang penyelenggaraan urusan pemerintahan daerah.', CHAR(10), CHAR(10), 'Peraturan Gubernur Jawa Tengah Nomor 30 Tahun 2021 tentang Pedoman Pengelolaan Belanja Hibah Dan Bantuan Sosial Yang Bersumber Dari Anggaran Pendapatan Dan Belanja Daerah Provinsi Jawa Tengah')),
